INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(14801, 'Psalms 110:3', 'Psalms', 110, 3, '&nbsp;کله چې تۀ دشمن سره په جنګ شې نو ستا خلق به په خپله رضا تا ته راشى. د تقوىٰ او پرهيزګارۍ په لباس به سمبال شوى تا ته راشى، لکه د پرخې په شان به سحر وختى په مقدس غر به خپل ځوانان تا ته راشى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14802, 'Psalms 110:4', 'Psalms', 110, 4, '&nbsp;مالِک خُدائ قسم خوړلے دے او خپله فېصله به نۀ بدلوى، ”تۀ به لکه د مَلِک‌صِدق د تل دپاره اِمام يې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14803, 'Psalms 110:5', 'Psalms', 110, 5, '&nbsp;مالِک خُدائ ستا ښى لاس ته ولاړ دے، په خپل قهر او غضب کښې به ډېر بادشاهان ووهى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14804, 'Psalms 110:6', 'Psalms', 110, 6, '&nbsp;هغه به د قومونو عدالت وکړى او د مړو به ډيرى ولګوى، او په زمکه به د ټولو بادشاهانو سرونه چخڼى کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14805, 'Psalms 110:7', 'Psalms', 110, 7, '&nbsp;خو بادشاه به د لارې د ولې نه اوبۀ وڅښى، نو ځکه به هغه د کاميابۍ هسکه غړۍ ګرځوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14806, 'Psalms 111:1', 'Psalms', 111, 1, '&nbsp;د خُدائ ثناء ووايئ. زۀ به په خپل ټول زړۀ سره د مالِک خُدائ لوئى بيان کړم، کله چې زۀ د هغۀ د نېکو خلقو سره په جماعت کښې مِلاو شم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14807, 'Psalms 111:2', 'Psalms', 111, 2, '&nbsp;د مالِک خُدائ کارونه ډېر لوئ دى، څوک چې په دې فکر کوى نو په هغې کښې خوشحاله دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14808, 'Psalms 111:3', 'Psalms', 111, 3, '&nbsp;د هغۀ کارونه د جلال او لويئ نه ډک دى، او د هغۀ صداقت د تل دپاره ‎پاتې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14809, 'Psalms 111:4', 'Psalms', 111, 4, '&nbsp;د هغۀ معجزې به خلق تل يادې ساتى، زمونږ مالِک خُدائ بخښونکے او مهربان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14810, 'Psalms 111:5', 'Psalms', 111, 5, '&nbsp;د هغۀ نه چې څوک يريږى هغوئ ته رزق ورکوى، هغه خپل لوظ د تل دپاره ياد ساتى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14811, 'Psalms 111:6', 'Psalms', 111, 6, '&nbsp;هغۀ خپلو خلقو ته د خپلو کارونو زور ښودلے دے، او هغوئ ته يې د نورو قومونو زمکې ورکړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14812, 'Psalms 111:7', 'Psalms', 111, 7, '&nbsp;د هغۀ د لاس ټول کارونه په اِنصاف او ښۀ دى، او د هغۀ ټول اصُولونه اعتبارى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14813, 'Psalms 111:8', 'Psalms', 111, 8, '&nbsp;او هغه تر ابده قائم پاتې کېدونکى دى، او دا ټول په وفادارۍ او صداقت سره شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14814, 'Psalms 111:9', 'Psalms', 111, 9, '&nbsp;هغۀ د خپلو خلقو دپاره کفاره ورکړه، هغۀ خپل لوظ تر ابده پورې قائم کړو، د هغۀ نوم مقدس دے او شان او شوکت لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14815, 'Psalms 111:10', 'Psalms', 111, 10, '&nbsp;د مالِک خُدائ نه يره کول د حکمت شروع ده، هر هغه څوک چې د هغۀ قانون منى هغه هوښيار دے، د تل دپاره به د هغۀ ثناء صِفت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14816, 'Psalms 112:1', 'Psalms', 112, 1, '&nbsp;د مالِک خُدائ ثناء صِفت دې وى، بختور دى هغوئ څوک چې د مالِک خُدائ نه يريږى، او څوک چې د هغۀ په حُکمونو په عمل کولو ډېر خوشحاله وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14817, 'Psalms 112:2', 'Psalms', 112, 2, '&nbsp;د هغوئ اولاد به په زمکه زورَور خلق شى، د صادقانو نسل به بختور کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14818, 'Psalms 112:3', 'Psalms', 112, 3, '&nbsp;دولت او مالدارى به د هغۀ په کور کښې وى، او د هغۀ صداقت به د تل دپاره وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14819, 'Psalms 112:4', 'Psalms', 112, 4, '&nbsp;کۀ څۀ هم په تيارۀ کښې صادقانو ته رڼا ځليږى، څوک چې مِهربانه زړۀ سواندى او صادق وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14820, 'Psalms 112:5', 'Psalms', 112, 5, '&nbsp;مِهربانه په هغۀ دے چې سخى وى او بل ته بې‌لالچه قرض ورکوى، او څوک چې خپلې مسئلې په اِنصاف سره حل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14821, 'Psalms 112:6', 'Psalms', 112, 6, '&nbsp;په يقين سره هغه به ونۀ خوځولے شى، صادق سړے به تل يادولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14822, 'Psalms 112:7', 'Psalms', 112, 7, '&nbsp;هغه به د بد خبر نه نۀ يريږى، د هغۀ زړۀ قائم دے او په مالِک خُدائ باندې پوره توکل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14823, 'Psalms 112:8', 'Psalms', 112, 8, '&nbsp;د هغۀ زړۀ مطمئن دے او هغه به نۀ يريږى، او په آخر کښې به په خپلو ټولو دشمنانو کاميابى حاصله کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14824, 'Psalms 112:9', 'Psalms', 112, 9, '&nbsp;هغۀ خپل خېراتونه مسکينانو ته ورلېږلى دى، د هغۀ صداقت د تل دپاره پاتې کيږى، او د عزت سره به د هغۀ سترګې اوچتيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14825, 'Psalms 112:10', 'Psalms', 112, 10, '&nbsp;بدکاران چې دا ګورى نو غصه کيږى، او هغوئ به خپل غاښونه چيچى او ورک به شى، د بدکارانو ارمانونه به پوره نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14826, 'Psalms 113:1', 'Psalms', 113, 1, '&nbsp;مالِک خُدائ ته دې ثناء صِفت وى. اے د مالِک خُدائ خِدمتګارانو د هغۀ ثناء صِفت وکړئ، او د مالِک خُدائ د نوم ثناء صِفت وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14827, 'Psalms 113:2', 'Psalms', 113, 2, '&nbsp;د مالِک خُدائ نوم ته دې ثناء صِفت وى، د اوس نه تر ابده پورې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14828, 'Psalms 113:3', 'Psalms', 113, 3, '&nbsp;د نمر ختو نه د نمر پرېوتو پورې، د مالِک خُدائ د نوم ستائينه دې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14829, 'Psalms 113:4', 'Psalms', 113, 4, '&nbsp;مالِک خُدائ په ټولو قومونو کښې اوچت دے، او د هغۀ جلال پاس په آسمانونو کښې دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14830, 'Psalms 113:5', 'Psalms', 113, 5, '&nbsp;زمونږ د مالِک خُدائ خُدائ پاک په شان بل څوک دے، هغه څوک چې پاس په آسمان کښې په تخت ناست دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14831, 'Psalms 113:6', 'Psalms', 113, 6, '&nbsp;څوک چې خپل ځان په دې عاجزوى چې آسمانونو او زمکې ته لاندې ګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14832, 'Psalms 113:7', 'Psalms', 113, 7, '&nbsp;هغه غريبان د خاورو نه اوچتوى، او هغه حاجتمند د ايرو نه اوچتوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14833, 'Psalms 113:8', 'Psalms', 113, 8, '&nbsp;هغوئ د شهزادګانو سره کښېنوى، او تر دې هغوئ د خپلو شهزادګانو سره کښېنوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14834, 'Psalms 113:9', 'Psalms', 113, 9, '&nbsp;هغه شنډې ښځې په خپلو کورونو کښې داسې خوشحالوى، لکه يوه خوشحاله د بچو مور چې وى. مالِک خُدائ ته دې ثناء صِفت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14835, 'Psalms 114:1', 'Psalms', 114, 1, '&nbsp;کله چې بنى اِسرائيليان د مِصر نه بهر راووتل، او د يعقوب خاندان چې د پردى مُلک نه راووتل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14836, 'Psalms 114:2', 'Psalms', 114, 2, '&nbsp;يهوداه د خُدائ مقدس ځائ شو، او اِسرائيل د خُدائ پاک د بادشاهت ځائ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14837, 'Psalms 114:3', 'Psalms', 114, 3, '&nbsp;کله چې بحرِقُلزم دوئ وليدل نو لار يې ورته پرېښوده، او د اُردن سيند واپس شو او خپل ځائ ته لاړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14838, 'Psalms 114:4', 'Psalms', 114, 4, '&nbsp;غرونو لکه د ګډانو په شان منډې کړې، او غونډو لکه د ګډورو په شان منډې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14839, 'Psalms 114:5', 'Psalms', 114, 5, '&nbsp;اے سمندره دا څۀ چل وو چې تا هغوئ ته لار پرېښوده، تۀ ولې واپس شوې اے د اُردن سينده،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14840, 'Psalms 114:6', 'Psalms', 114, 6, '&nbsp;غرونو تاسو ولې لکه د ګډانو په شان منډې کړې؟ او تاسو اے غونډو ولې لکه د ګډورو په شان منډې کړې؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14841, 'Psalms 114:7', 'Psalms', 114, 7, '&nbsp;د مالِک خُدائ په راتلو سره اے زمکې په لړزان شه، د يعقوب د پاک خُدائ په حضور کښې په لړزان شه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14842, 'Psalms 114:8', 'Psalms', 114, 8, '&nbsp;چا چې د ګټ نه د اوبو تالاب جوړ کړو، او سخت ګټ نه يې د اوبو چشمه جوړه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14843, 'Psalms 115:1', 'Psalms', 115, 1, '&nbsp;مونږ ته نه، اے مالِکه خُدايه، مونږ ته نه، خو ستا نوم ته دې جلال وى، ځکه ستا د مينې او وفا په سبب دې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14844, 'Psalms 115:2', 'Psalms', 115, 2, '&nbsp;قومونه ولې وائى چې، ”د دوئ پاک خُدائ چرته دے؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14845, 'Psalms 115:3', 'Psalms', 115, 3, '&nbsp;زمونږ پاک خُدائ په آسمان کښې دے، هر هغه څۀ کوى چې څۀ د هغۀ خوښ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14846, 'Psalms 115:4', 'Psalms', 115, 4, '&nbsp;خو د هغوئ بُتان د سرو او سپينو زرو دى، چې د انسانانو په لاسونو جوړ شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14847, 'Psalms 115:5', 'Psalms', 115, 5, '&nbsp;د هغوئ خولې شته خو خبرې پرې کولے نۀ شى، سترګې يې هم شته خو پرې ليدلے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14848, 'Psalms 115:6', 'Psalms', 115, 6, '&nbsp;د هغوئ غوږونه شته خو پرې اورېدلے نۀ شى، پوزې يې هم شته خو پرې بويولے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14849, 'Psalms 115:7', 'Psalms', 115, 7, '&nbsp;د هغوئ لاسونه هم شته خو پرې څۀ محسوسولے نۀ شى، د هغوئ پښې هم شته خو پرې ګرځېدلے نۀ شى، خو هيڅ قسمه آواز د مرۍ نه ويستلے نۀ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14850, 'Psalms 115:8', 'Psalms', 115, 8, '&nbsp;چا چې دا جوړ کړى دى نو د هغوئ په شان به شى، او بيا هم هغوئ ټول، څوک چې پرې يقين لرى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14851, 'Psalms 115:9', 'Psalms', 115, 9, '&nbsp;اے بنى اِسرائيلو په مالِک خُدائ باندې توکل کوئ، هغه ستاسو ډال دے او ستا مدد کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14852, 'Psalms 115:10', 'Psalms', 115, 10, '&nbsp;اے د هارون خاندانه په مالِک خُدائ باندې توکل کوئ، هغه ستاسو ډال دے او مدد کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14853, 'Psalms 115:11', 'Psalms', 115, 11, '&nbsp;اے تاسو چې د هغۀ نه يره کوئ په مالِک خُدائ باندې توکل کوئ، هغه ستاسو ډال دے او مدد کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14854, 'Psalms 115:12', 'Psalms', 115, 12, '&nbsp;مالِک خُدائ ته مونږ ياد يُو او برکت به راکړى، هغه به د بنى اِسرائيلو خاندان له برکت ورکړى، هغه به د هارون خاندان له برکت ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14855, 'Psalms 115:13', 'Psalms', 115, 13, '&nbsp;هغه به هغه چا له برکت ورکړى څوک چې د مالِک خُدائ نه يريږى، لويو او واړو ټولو ته به يو شان ملاويږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14856, 'Psalms 115:14', 'Psalms', 115, 14, '&nbsp;مالِک خُدائ دې تاسو زيات کړى، تاسو او ستاسو د بچو نسل دې زيات کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14857, 'Psalms 115:15', 'Psalms', 115, 15, '&nbsp;مالِک خُدائ دې تاسو له برکت درکړى، څوک چې د آسمان او زمکې خالق دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14858, 'Psalms 115:16', 'Psalms', 115, 16, '&nbsp;اوچت آسمانونه د مالِک خُدائ دى، خو زمکه يې انسان له ورکړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14859, 'Psalms 115:17', 'Psalms', 115, 17, '&nbsp;مړى خو د مالِک خُدائ ثناء صِفت نۀ کوى، هغوئ څوک چې لاندې خاموشۍ طرف ته روان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14860, 'Psalms 115:18', 'Psalms', 115, 18, '&nbsp;خو مونږ يُو چې د مالِک خُدائ ثناء صِفت کوُو، په دواړه وختونو کښې اوس هم او د تل دپاره هم لوئى بيانوو، د مالِک خُدائ ثناء صِفت دې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14861, 'Psalms 116:1', 'Psalms', 116, 1, '&nbsp;د مالِک خُدائ سره مينه کوم ځکه چې هغۀ زما سوال زارى اورېدلې ده، هغۀ زما سوال زارى د رحم دپاره اورېدلې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14862, 'Psalms 116:2', 'Psalms', 116, 2, '&nbsp;ځکه چې هغه اوس په ما خيال ساتى او خپل غوږ يې ما ته راړولے دے، ترڅو چې زۀ ژوندے يم زۀ به هغۀ نه سوال کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14863, 'Psalms 116:3', 'Psalms', 116, 3, '&nbsp;د مرګ پړو راګېر کړے يم، د قبر سخته په ما راغلې ده، زۀ په خپل خفګان او تکليفونو کښې ډوب شوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14864, 'Psalms 116:4', 'Psalms', 116, 4, '&nbsp;نو ما بيا د مالِک خُدائ په نوم چغه کړه، چې، ”اے مالِکه خُدايه ما بچ کړه.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14865, 'Psalms 116:5', 'Psalms', 116, 5, '&nbsp;مالِک خُدائ مهربانه او صادق دے، زمونږ خُدائ پاک پوره رحيم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14866, 'Psalms 116:6', 'Psalms', 116, 6, '&nbsp;مالِک خُدائ ساده زړۀ لرونکى خلق بچ کوى، کله چې زۀ ډېر سخت حاجتمند ومه هغۀ زۀ بچ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14867, 'Psalms 116:7', 'Psalms', 116, 7, '&nbsp;نو زما روحه يو ځل بيا خپل آرام ته راشه، ځکه چې مالِک خُدائ ما سره ښۀ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14868, 'Psalms 116:8', 'Psalms', 116, 8, '&nbsp;خو تا په خپله اے مالِکه خُدايه زما روح د مرګ نه بچ کړو، زما سترګې دې د اوښکو نه اوچې کړې، زما پښې دې د تيندک خوړلو نه بچ کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14869, 'Psalms 116:9', 'Psalms', 116, 9, '&nbsp;نو بيا به زۀ د مالِک خُدائ په وړاندې، د ژوندو په مُلک کښې وګرځم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14870, 'Psalms 116:10', 'Psalms', 116, 10, '&nbsp;نو زما دا ايمان وو نو ځکه ما ووئيل چې، ”زۀ ډېر په تکليف کښې يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14871, 'Psalms 116:11', 'Psalms', 116, 11, '&nbsp;او ما په خپله مايوسۍ کښې دا ووئيل چې، ”ټول انسانان دروغژن دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14872, 'Psalms 116:12', 'Psalms', 116, 12, '&nbsp;نو زۀ به څنګه مالِک خُدائ له د هغې بدل خلاص کړم، د هغۀ د ټولو هغه ښېګړو چې ما سره يې کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14873, 'Psalms 116:13', 'Psalms', 116, 13, '&nbsp;زۀ به د خلاصون جام اوچت کړم، او زۀ به د مالِک خُدائ په نوم سوال زارى وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14874, 'Psalms 116:14', 'Psalms', 116, 14, '&nbsp;زۀ به د مالِک خُدائ سره خپلې ټولې وعدې پوره کړم، د هغۀ د ټولو خلقو په وړاندې به خپلې وعدې پوره کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14875, 'Psalms 116:15', 'Psalms', 116, 15, '&nbsp;د مالِک خُدائ په نظر کښې د هغۀ د مقدسينو مرګ ډېر اهم دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14876, 'Psalms 116:16', 'Psalms', 116, 16, '&nbsp;اے مالِکه خُدايه په رښتيا سره ستا خِدمتګار يم، لکه ستا د وينځې د زوئ په شان زۀ ستا خِدمتګار يم، تا زۀ د زنځيرونو نه آزاد کړے يمه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14877, 'Psalms 116:17', 'Psalms', 116, 17, '&nbsp;زۀ به تا ته د شُکر ګزارۍ قربانى وکړم، او د مالِک خُدائ په نوم به دُعا وغواړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14878, 'Psalms 116:18', 'Psalms', 116, 18, '&nbsp;زۀ به د مالِک خُدائ سره خپلې ټولې وعدې پوره کړم، د هغۀ د ټولو خلقو په وړاندې به خپلې وعدې پوره کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14879, 'Psalms 116:19', 'Psalms', 116, 19, '&nbsp;د مالِک خُدائ د کور په دربار کښې يروشلمه ستا په مينځ کښې مالِک خُدائ ته دې ثناء صِفت وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14880, 'Psalms 117:1', 'Psalms', 117, 1, '&nbsp;اے ټولو قومونو د مالِک خُدائ ثناء صِفت وکړئ، اے ټولو خلقو د هغۀ لوئى بيان کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14881, 'Psalms 117:2', 'Psalms', 117, 2, '&nbsp;ځکه چې زمونږ دپاره د هغۀ مينه ډېره لويه ده، او د مالِک خُدائ وفادارى د تل دپاره ده، ثناء صِفت دې مالِک خُدائ ته وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14882, 'Psalms 118:1', 'Psalms', 118, 1, '&nbsp;د مالِک خُدائ شُکر وباسئ ځکه چې هغه ښۀ دے، د هغۀ مينه د تل دپاره پاتې کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14883, 'Psalms 118:2', 'Psalms', 118, 2, '&nbsp;بنى اِسرائيل دې داسې ووائى، ”د هغۀ مينه د تل دپاره پاتې کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14884, 'Psalms 118:3', 'Psalms', 118, 3, '&nbsp;د هارون خاندان دې داسې ووائى، ”د هغۀ مينه د تل دپاره پاتې کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14885, 'Psalms 118:4', 'Psalms', 118, 4, '&nbsp;هغوئ څوک چې د مالِک خُدائ نه يريږى، دې ووائى، ”د هغۀ مينه د تل دپاره پاتې کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14886, 'Psalms 118:5', 'Psalms', 118, 5, '&nbsp;ما په سخته کښې مالِک خُدائ ته سوال زارى وکړه، هغۀ زما سوال قبول کړو او زۀ يې آزاد کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14887, 'Psalms 118:6', 'Psalms', 118, 6, '&nbsp;مالِک خُدائ زما مل دے زۀ به نۀ يرېږم، انسان زما څۀ کولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14888, 'Psalms 118:7', 'Psalms', 118, 7, '&nbsp;مالِک خُدائ زما مل دے او هغه زما مددګار دے، زۀ به د خپلو دشمنانو په شکست خوشحالى وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14889, 'Psalms 118:8', 'Psalms', 118, 8, '&nbsp;دا ښۀ ده چې په مالِک خُدائ کښې پناه واخلم، د دې په ځائ چې په بنيادم توکل وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14890, 'Psalms 118:9', 'Psalms', 118, 9, '&nbsp;دا بهتره ده چې په مالِک خُدائ کښې پناه واخلم، نه چې په شهزادګانو توکل وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14891, 'Psalms 118:10', 'Psalms', 118, 10, '&nbsp;زۀ ټولو قومونو راګېر کړم، خو د مالِک خُدائ په نوم مې هغوئ مات کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14892, 'Psalms 118:11', 'Psalms', 118, 11, '&nbsp;زۀ هغوئ د هر طرف نه راګېر کړم، خو د مالِک خُدائ په نوم مې هغوئ مات کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14893, 'Psalms 118:12', 'Psalms', 118, 12, '&nbsp;هغوئ زما نه لکه د مچو په شان راتاو شُو، لکه د ازغو د اور په شان زر هلاک شُو، خو د مالِک خُدائ په نوم مې هغوئ مات کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14894, 'Psalms 118:13', 'Psalms', 118, 13, '&nbsp;هغوئ ما له سخته ديکه راکړه چې راپرېوځم، خو مالِک خُدائ زما مدد وکړو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14895, 'Psalms 118:14', 'Psalms', 118, 14, '&nbsp;مالِک خُدائ زما سندره او طاقت دے، هغه زما خلاصونکے جوړ شوے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14896, 'Psalms 118:15', 'Psalms', 118, 15, '&nbsp;د خوشحالۍ او د کاميابۍ چغې د صادقانو په خېمو کښې اورېدے شى، ”د مالِک خُدائ ښى لاس زورَور کارونه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14897, 'Psalms 118:16', 'Psalms', 118, 16, '&nbsp;د مالِک خُدائ ښے لاس ډېر اوچت دے، د مالِک خُدائ ښى لاس زورَور کارونه کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14898, 'Psalms 118:17', 'Psalms', 118, 17, '&nbsp;زۀ به نۀ مرم خو ژوندے به يم، او هغه څۀ چې مالِک خُدائ کړى دى بيانوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14899, 'Psalms 118:18', 'Psalms', 118, 18, '&nbsp;مالِک خُدائ ما ته سخته سزا راکړه، خو زۀ هغۀ مرګ ته حواله نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(14900, 'Psalms 118:19', 'Psalms', 118, 19, '&nbsp;هغۀ ما دپاره د صداقت دروازې پرانستې دى، زۀ به په کښې وردننه شم او د مالِک خُدائ شکريه به ادا کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');